// TypeScript Model: Primary Dealer Underwriting Commitment & Devolvement Engine
interface SovereignAuctionParams {
  totalAuctionNotionalCrores: number; // e.g., 32,000 Cr
  benchmarkTenorYears: number;        // e.g., 10Y
  indicativeCouponRate: number;       // e.g., 0.0710 (7.10%)
  underwritingCommissionBps: number;  // e.g., 12.5 bps (0.125%)
}

interface PrimaryDealerObligation {
  pdName: string;
  underwritingQuotaPercent: number;   // e.g., 0.075 (7.5%)
  clientBidsCollectedCrores: number;  // e.g., 1,800 Cr
  proprietaryBidCrores: number;       // e.g., 200 Cr
}

function evaluatePrimaryDealerDevolvement(
  auction: SovereignAuctionParams,
  pd: PrimaryDealerObligation
) {
  const committedUnderwritingNotional = auction.totalAuctionNotionalCrores * pd.underwritingQuotaPercent;
  const totalBidsSubmitted = pd.clientBidsCollectedCrores + pd.proprietaryBidCrores;

  const isDevolved = totalBidsSubmitted < committedUnderwritingNotional;
  const devolvementNotional = isDevolved ? committedUnderwritingNotional - totalBidsSubmitted : 0;

  const totalAllocatedToPd = totalBidsSubmitted + devolvementNotional;
  const totalCommissionEarned = committedUnderwritingNotional * (auction.underwritingCommissionBps / 10000);

  return {
    pdName: pd.pdName,
    committedUnderwritingCrores: committedUnderwritingNotional,
    totalBidsSubmittedCrores: totalBidsSubmitted,
    isDevolved,
    devolvementNotionalCrores: devolvementNotional,
    devolvementRatioPercent: (devolvementNotional / committedUnderwritingNotional) * 100,
    totalAllocatedToPdCrores: totalAllocatedToPd,
    underwritingCommissionEarnedCrores: totalCommissionEarned
  };
}

// TypeScript Model: Uniform Price vs Multiple Price Sovereign Auction Simulator
interface CompetitiveBid {
  bidderName: string;
  yieldBidPercent: number; // e.g., 7.08%
  notionalCrores: number;  // e.g., 3,000 Cr
}

interface AuctionResult {
  auctionFormat: 'UNIFORM_PRICE' | 'MULTIPLE_PRICE';
  totalIssueSizeCrores: number;
  cutOffYieldPercent: number;
  weightedAverageYieldPercent: number;
  allocations: Array<{
    bidderName: string;
    allottedNotionalCrores: number;
    effectiveSettlementYieldPercent: number;
  }>;
  sovereignAnnualInterestExpenseCrores: number;
}

function executeSovereignAuction(
  issueSizeCrores: number,
  format: 'UNIFORM_PRICE' | 'MULTIPLE_PRICE',
  rawBids: CompetitiveBid[]
): AuctionResult {
  // Sort bids in ascending order of yield (lowest yield = highest price = most aggressive)
  const sortedBids = [...rawBids].sort((a, b) => a.yieldBidPercent - b.yieldBidPercent);

  let cumulativeAllotted = 0;
  let cutOffYield = 0;
  const acceptedBids: Array<{ bidderName: string; allotted: number; bidYield: number }> = [];

  for (const bid of sortedBids) {
    if (cumulativeAllotted >= issueSizeCrores) break;
    const remainingNeeded = issueSizeCrores - cumulativeAllotted;
    const allocation = Math.min(bid.notionalCrores, remainingNeeded);

    cumulativeAllotted += allocation;
    cutOffYield = bid.yieldBidPercent;
    acceptedBids.push({ bidderName: bid.bidderName, allotted: allocation, bidYield: bid.yieldBidPercent });
  }

  let totalWeightedYield = 0;
  const finalAllocations = acceptedBids.map(b => {
    const settlementYield = (format === 'UNIFORM_PRICE') ? cutOffYield : b.bidYield;
    totalWeightedYield += b.allotted * settlementYield;
    return {
      bidderName: b.bidderName,
      allottedNotionalCrores: b.allotted,
      effectiveSettlementYieldPercent: settlementYield
    };
  });

  const weightedAvgYield = totalWeightedYield / issueSizeCrores;
  const annualInterest = (totalWeightedYield / 100);

  return {
    auctionFormat: format,
    totalIssueSizeCrores: issueSizeCrores,
    cutOffYieldPercent: cutOffYield,
    weightedAverageYieldPercent: weightedAvgYield,
    allocations: finalAllocations,
    sovereignAnnualInterestExpenseCrores: annualInterest
  };
}

// TypeScript Model: STRIPS Decomposition & Zero-Coupon Cash Flow Engine
interface CouponBondParams {
  faceValueCrores: number;       // e.g., 100 Cr
  tenorYears: number;            // e.g., 10Y
  annualCouponRate: number;      // e.g., 0.080 (8.00%)
  couponFrequencyPerYear: number;// 2 (semi-annual)
  zeroCurveYield: number;        // e.g., 0.072 (7.20%)
}

interface StripSecurity {
  isinSuffix: string;
  type: 'COUPON_STRIP' | 'PRINCIPAL_STRIP';
  maturityYears: number;
  cashFlowCrores: number;
  discountedMarketPricePercent: number;
  marketValueCrores: number;
  macaulayDurationYears: number;
}

function decomposeBondIntoStrips(bond: CouponBondParams): {
  strips: StripSecurity[];
  totalStripsMarketValueCrores: number;
  originalBondParCrores: number;
} {
  const strips: StripSecurity[] = [];
  const totalPeriods = bond.tenorYears * bond.couponFrequencyPerYear;
  const periodCouponCashFlow = (bond.faceValueCrores * (bond.annualCouponRate / bond.couponFrequencyPerYear));
  const periodicYield = bond.zeroCurveYield / bond.couponFrequencyPerYear;

  let totalMarketValue = 0;

  // Generate Coupon STRIPS
  for (let p = 1; p <= totalPeriods; p++) {
    const maturityYears = p / bond.couponFrequencyPerYear;
    const discountFactor = Math.pow(1 + periodicYield, p);
    const marketVal = periodCouponCashFlow / discountFactor;
    const pricePercent = (marketVal / periodCouponCashFlow) * 100;

    totalMarketValue += marketVal;
    strips.push({
      isinSuffix: `C-${p.toString().padStart(2, '0')}`,
      type: 'COUPON_STRIP',
      maturityYears,
      cashFlowCrores: periodCouponCashFlow,
      discountedMarketPricePercent: pricePercent,
      marketValueCrores: marketVal,
      macaulayDurationYears: maturityYears
    });
  }

  // Generate Principal STRIP
  const principalDiscountFactor = Math.pow(1 + periodicYield, totalPeriods);
  const principalMarketVal = bond.faceValueCrores / principalDiscountFactor;
  const principalPricePercent = (principalMarketVal / bond.faceValueCrores) * 100;
  totalMarketValue += principalMarketVal;

  strips.push({
    isinSuffix: `P-${bond.tenorYears}Y`,
    type: 'PRINCIPAL_STRIP',
    maturityYears: bond.tenorYears,
    cashFlowCrores: bond.faceValueCrores,
    discountedMarketPricePercent: principalPricePercent,
    marketValueCrores: principalMarketVal,
    macaulayDurationYears: bond.tenorYears
  });

  return {
    strips,
    totalStripsMarketValueCrores: totalMarketValue,
    originalBondParCrores: bond.faceValueCrores
  };
}

// TypeScript Model: Nelson-Siegel Sovereign Yield Curve Parameterization Engine
interface NelsonSiegelParams {
  beta0_level: number;     // Asymptotic long-term rate (e.g., 0.0750 = 7.50%)
  beta1_slope: number;     // Short-rate differential (e.g., -0.0150 = -1.50%)
  beta2_curvature: number; // Mid-term hump (e.g., -0.0080 = -0.80%)
  tau_scale: number;       // Maturity scale parameter in years (e.g., 2.5Y)
}

function calculateNelsonSiegelSpotRate(t: number, p: NelsonSiegelParams): number {
  if (t <= 0.001) return p.beta0_level + p.beta1_slope;

  const theta = t / p.tau_scale;
  const expTerm = Math.exp(-theta);

  // Factor 1 loading: (1 - e^-theta) / theta
  const factor1 = (1 - expTerm) / theta;

  // Factor 2 loading: ((1 - e^-theta) / theta) - e^-theta
  const factor2 = factor1 - expTerm;

  const spotRate = p.beta0_level + (p.beta1_slope * factor1) + (p.beta2_curvature * factor2);
  return spotRate;
}

function generateSovereignSpotCurve(p: NelsonSiegelParams, tenors: number[]) {
  return tenors.map(tenor => {
    const spot = calculateNelsonSiegelSpotRate(tenor, p);
    return {
      tenorYears: tenor,
      spotRatePercent: spot * 100,
      discountFactor: 1 / Math.pow(1 + spot, tenor)
    };
  });
}

// Run Nelson-Siegel Calibration
const nsParams: NelsonSiegelParams = {
  beta0_level: 0.0750,
  beta1_slope: -0.0150,
  beta2_curvature: -0.0080,
  tau_scale: 2.5
};

const sovereignCurve = generateSovereignSpotCurve(nsParams, [0.25, 0.5, 1.0, 2.0, 3.0, 5.0, 7.0, 10.0, 15.0, 30.0]);
console.log('Calibrated Nelson-Siegel Sovereign Spot Curve:');
sovereignCurve.forEach(pt => {
  console.log(`- Tenor: ${pt.tenorYears.toFixed(2)}Y | Spot Rate: ${pt.spotRatePercent.toFixed(2)}% | Discount Factor: ${pt.discountFactor.toFixed(4)}`);
});

// Industrial TypeScript Simulation: Sovereign Auction Underwriting & STRIPS Lab
interface SovereignAuctionTranche {
  tenorYears: number;             // e.g., 10Y or 30Y
  notionalCrores: number;         // e.g., 20,000 Cr or 15,000 Cr
  indicativeCouponPercent: number;// e.g., 7.10% or 7.45%
  pdUnderwritingQuotaRate: number;// e.g., 0.08 (8%)
  clientBidsReceivedCrores: number;// e.g., 1,200 Cr or 900 Cr
  commissionBps: number;          // e.g., 12.5 bps
}

interface SovereignWarRoomConfig {
  auctionFormat: 'UNIFORM_PRICE' | 'MULTIPLE_PRICE';
  tenYearTranche: SovereignAuctionTranche;
  thirtyYearTranche: SovereignAuctionTranche;
  nsLevelBeta0: number;           // 0.0750 (7.50%)
  nsSlopeBeta1: number;           // -0.0150
  nsCurvatureBeta2: number;       // -0.0080
  nsTauScale: number;             // 2.5
}

function runSovereignPrimaryWarRoom(config: SovereignWarRoomConfig) {
  console.log('=== INDUSTRIAL SOVEREIGN PRIMARY AUCTION & STRIPS LAB ===');
  console.log(`Auction Format Selected: ${config.auctionFormat}`);

  const tranches = [config.tenYearTranche, config.thirtyYearTranche];
  let totalUnderwritingCommitment = 0;
  let totalDevolvement = 0;
  let totalCommissionEarned = 0;

  tranches.forEach(tranche => {
    const quotaCrores = tranche.notionalCrores * tranche.pdUnderwritingQuotaRate;
    totalUnderwritingCommitment += quotaCrores;

    const shortfall = Math.max(0, quotaCrores - tranche.clientBidsReceivedCrores);
    totalDevolvement += shortfall;

    const commission = quotaCrores * (tranche.commissionBps / 10000);
    totalCommissionEarned += commission;

    console.log(`
Tranche: ${tranche.tenorYears}Y Sovereign Bond (Issue Size: ₹${tranche.notionalCrores.toLocaleString()} Cr)`);
    console.log(`  Assigned PD Underwriting Quota (8.0%): ₹${quotaCrores.toLocaleString()} Cr`);
    console.log(`  Client Bids Mobilized: ₹${tranche.clientBidsReceivedCrores.toLocaleString()} Cr`);
    console.log(`  Devolvement Incurred: ₹${shortfall.toLocaleString()} Cr (${shortfall > 0 ? '⚠️ DEVOLUTION OCCURRED' : 'FULLY COVERED'})`);
    console.log(`  Underwriting Commission Earned: ₹${commission.toFixed(2)} Cr`);
  });

  console.log('---------------------------------------------------------');
  console.log(`Total Underwriting Quota Committed: ₹${totalUnderwritingCommitment.toLocaleString()} Cr`);
  console.log(`Total Auction Devolvement Absorbed: ₹${totalDevolvement.toLocaleString()} Cr`);
  console.log(`Total Underwriting Commission Cash: ₹${totalCommissionEarned.toFixed(2)} Cr`);

  // PART B: STRIPS STRUCTURING OF DEVOLVED 30-YEAR INVENTORY
  console.log('
--- STRIPS DECOMPOSITION & PENSION SYNDICATION LAB ---');
  const devolved30Y = Math.max(0, (config.thirtyYearTranche.notionalCrores * config.thirtyYearTranche.pdUnderwritingQuotaRate) - config.thirtyYearTranche.clientBidsReceivedCrores);
  console.log(`Initiating Chemical Decomposition on ₹${devolved30Y.toLocaleString()} Cr of 30Y Sovereign Bonds`);

  // Nelson-Siegel 30Y Spot Rate
  const theta30 = 30.0 / config.nsTauScale;
  const expTerm30 = Math.exp(-theta30);
  const factor1_30 = (1 - expTerm30) / theta30;
  const factor2_30 = factor1_30 - expTerm30;
  const spot30Y = config.nsLevelBeta0 + (config.nsSlopeBeta1 * factor1_30) + (config.nsCurvatureBeta2 * factor2_30);

  // Principal STRIP Price = 1 / (1 + spot/2)^(2*30)
  const discountPeriods = 30 * 2;
  const semiAnnualYield = spot30Y / 2;
  const principalStripPrice = (1 / Math.pow(1 + semiAnnualYield, discountPeriods)) * 100;
  const principalStripMarketValue = (devolved30Y * (principalStripPrice / 100));

  console.log(`Nelson-Siegel Calibrated 30Y Zero-Coupon Spot Rate: ${(spot30Y * 100).toFixed(2)}%`);
  console.log(`30Y Principal STRIP Benchmark Price: ${principalStripPrice.toFixed(2)}% of Par`);
  console.log(`30Y Principal STRIP Market Value: ₹${principalStripMarketValue.toFixed(2)} Cr`);

  // Private placement with life insurer at a 5 bps yield compression
  const institutionalPlacementYield = spot30Y - 0.0005; // 5 bps premium
  const institutionalPrice = (1 / Math.pow(1 + (institutionalPlacementYield / 2), discountPeriods)) * 100;
  const premiumSalesValue = devolved30Y * (institutionalPrice / 100);
  const arbitrageProfit = premiumSalesValue - principalStripMarketValue;

  console.log(`Syndicated to Pension Annuity Fund @ ${(institutionalPlacementYield * 100).toFixed(2)}% (Price: ${institutionalPrice.toFixed(2)}%)`);
  console.log(`STRIPS Institutional Distribution Profit: +₹${arbitrageProfit.toFixed(2)} Cr`);
  console.log(`Net Strategy Return (Commission + STRIPS Trading Alpha): +₹${(totalCommissionEarned + arbitrageProfit).toFixed(2)} Cr`);
  console.log('=========================================================');
}

// Run Simulation
runSovereignPrimaryWarRoom({
  auctionFormat: 'UNIFORM_PRICE',
  tenYearTranche: {
    tenorYears: 10,
    notionalCrores: 20000,
    indicativeCouponPercent: 7.10,
    pdUnderwritingQuotaRate: 0.08,
    clientBidsReceivedCrores: 1200,
    commissionBps: 12.5
